"""Embed the release solver into support/native_payload.py as text."""
import base64
import hashlib
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
BINARY = ROOT / "native/c4core/target/x86_64-unknown-linux-gnu/release/c4core"
OUTPUT = ROOT / "support/native_payload.py"


def main():
    raw = BINARY.read_bytes()
    packed = base64.b64encode(zlib.compress(raw, 9)).decode("ascii")
    digest = hashlib.sha256(raw).hexdigest()
    OUTPUT.write_text(
        '"""Embedded solver payload; generated by native/make_payload.py."""\n'
        f'PAYLOAD = "{packed}"\n'
        f'SHA256 = "{digest}"\n'
    )
    print(f"raw={len(raw)} packed={len(packed)} output={OUTPUT.stat().st_size} sha256={digest}")


if __name__ == "__main__":
    main()
